import java.io.*;import java.net.*;import java.util.*;
public class StageMJavaTcpClient{
 static void send(DataOutputStream o,String f,byte[] b)throws Exception{if(f.equals("fixed")){o.writeShort(b.length);o.write(b);}else if(f.equals("length_prefixed")){o.writeInt(b.length);o.write(b);}else{o.write(b);o.writeByte('\n');}o.flush();}
 static byte[] recv(DataInputStream in,String f)throws Exception{if(f.equals("line")){ByteArrayOutputStream b=new ByteArrayOutputStream();int x;while((x=in.read())!=-1&&x!='\n')b.write(x);return b.toByteArray();}int n=f.equals("fixed")?in.readUnsignedShort():in.readInt();byte[] b=new byte[n];in.readFully(b);return b;}
 public static void main(String[]a)throws Exception{if(a.length!=7)System.exit(2);String host=a[0],f=a[2];int port=Integer.parseInt(a[1]),count=Integer.parseInt(a[3]),req=Integer.parseInt(a[4]),resp=Integer.parseInt(a[5]),delay=Integer.parseInt(a[6]);try(Socket s=new Socket()){s.connect(new InetSocketAddress(host,port),5000);s.setSoTimeout(10000);DataInputStream in=new DataInputStream(s.getInputStream());DataOutputStream o=new DataOutputStream(s.getOutputStream());o.writeBytes("STAGEM1 "+f+" "+resp+"\n");o.flush();BufferedReader br=new BufferedReader(new InputStreamReader(in));String ack=br.readLine();if(!"OK".equals(ack))throw new RuntimeException("bad ack");List<Integer> lens=new ArrayList<>();for(int i=0;i<count;i++){byte[] b=new byte[req];Arrays.fill(b,(byte)(65+i%20));send(o,f,b);lens.add(recv(in,f).length);if(delay>0&&i+1<count)Thread.sleep(delay);}System.out.print("{\"reply_lengths\":[");for(int i=0;i<lens.size();i++){if(i>0)System.out.print(',');System.out.print(lens.get(i));}System.out.println("]}");}}
}
